/**
 * Left-sidebar footer toggle (ADR-003): restores/hides the right dock from
 * dsh's own left column, so the affordance NEVER overlaps web content (the
 * right 'details' column cannot reserve a collapsed width — only 0 or
 * [300, 520]). Dispatches the same TOGGLE_EVENT the global Ctrl/Cmd+Shift+B
 * shortcut uses; DockRoot listens and flips. Icon-only in the 56px rail,
 * icon + label in the wide sidebar.
 */
import type { ReactNode } from 'react'
import { ExpandIcon } from '../icons.tsx'
import { TOGGLE_EVENT } from './dock.tsx'
import type { TranslateNS } from '@deepseek-ai/dsh-client-ui-slots'
import css from './footer-toggle.module.css'

/** The footer entry component: receives the sidebar's { wide } owner share. */
export function createSidebarToggleAction(
  t: TranslateNS<'betterSidebar.dock'>,
): (props: { wide: boolean }) => ReactNode {
  const SidebarToggleAction = (props: { wide: boolean }): ReactNode => (
    <button
      type="button"
      className={props.wide ? css.wide : css.rail}
      aria-label={t('toggle.sidebar')}
      title={t('toggle.sidebar')}
      onClick={() => { window.dispatchEvent(new CustomEvent(TOGGLE_EVENT)) }}
    >
      <ExpandIcon size={props.wide ? 16 : 18} />
      {props.wide && <span className={css.label}>{t('toggle.sidebar')}</span>}
    </button>
  )
  return SidebarToggleAction
}